<?php
use yii\helpers\Html; use yii\widgets\ActiveForm; use yii\helpers\ArrayHelper; use kartik\select2\Select2;
$this->title='มอบหมายการประเมินทดลองงาน'; echo $this->render('_styles');
$employeeItems=ArrayHelper::map($employees,'id',fn($e)=>$e->fullname.' · '.($e->employeePosition->title??$e->position_name));
$templateItems=ArrayHelper::map($templates,'id',fn($t)=>$t->name.' · '.($t->positionGroup->title??''). ' (rev. '.$t->revision_no.')');
?>
<?php $personSelect=function($form,$model,$attribute,$data,$placeholder){ return $form->field($model,$attribute)->widget(Select2::class,['data'=>$data,'options'=>['placeholder'=>$placeholder],'pluginOptions'=>['allowClear'=>true]]); }; ?>
<div class="probation-shell"><header class="probation-head"><div><h1><?= Html::encode($this->title) ?></h1><p class="text-body-secondary">เลือกบุคลากร Template ตามวิชาชีพ และผู้รับผิดชอบตามลำดับ</p></div></header><div class="probation-card p-3 p-md-4"><?php $form=ActiveForm::begin(); ?><div class="row g-3"><div class="col-md-6"><?= $personSelect($form,$model,'employee_id',$employeeItems,'ค้นหาและเลือกบุคลากร') ?></div><div class="col-md-6"><?= $form->field($model,'template_id')->dropDownList($templateItems,['prompt'=>'เลือก Template']) ?></div><div class="col-md-4"><?= $form->field($model,'start_date')->input('date') ?></div><div class="col-md-4"><?= $personSelect($form,$model,'supervisor_employee_id',$employeeItems,'ค้นหาหัวหน้างาน') ?></div><div class="col-md-4"><?= $personSelect($form,$model,'group_head_employee_id',$employeeItems,'ค้นหาหัวหน้ากลุ่มงาน') ?></div><div class="col-md-6"><?= $personSelect($form,$model,'director_employee_id',$employeeItems,'ค้นหา ผอ.') ?></div><div class="col-md-6"><?= $personSelect($form,$model,'final_recommender_employee_id',$employeeItems,'เลือกผู้สรุปผล') ?><div class="form-text">ต้องเป็นหัวหน้างานหรือหัวหน้ากลุ่มงานที่เลือกไว้</div></div></div><div class="probation-form-actions"><?= Html::a('ยกเลิก',['index'],['class'=>'btn btn-outline-secondary']) ?><?= Html::submitButton('สร้างและมอบหมาย',['class'=>'btn btn-primary']) ?></div><?php ActiveForm::end(); ?></div></div>
